//! Linux-flavour command compactors.
//!
//! Each command lives in its own file (1 file per command, even with
//! thousands of files). New compactors only need:
//! 1. Create `cmd/linux/<command>.rs` with a `try_compact(&str) ->
//!    Option<String>` function. Return `None` when the detector
//!    doesn't match so the dispatch ladder can fall through.
//! 2. Optionally wire [`dispatch`] (content-shape ladder) and/or the
//!    [`crate::cmd::dispatch_named`] arm.
//!
//! The `pub mod` declarations are auto-generated by `build.rs` from
//! the directory contents — no `mod.rs` edit needed when adding files.

include!(concat!(env!("OUT_DIR"), "/cmd_linux_mods.rs"));

/// Content-shape dispatch — tries every Linux compactor in priority
/// order and returns the first match. Used when the program name is
/// unknown (Bash interceptor receives raw output). Only the
/// compactors with reasonably distinctive content shapes are listed
/// here; per-name dispatch through [`crate::cmd::dispatch_named`]
/// covers the rest.
pub fn dispatch(text: &str) -> Option<String> {
    if let Some(out) = ifconfig::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = ip::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = ping::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = traceroute::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = pacman::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = lsblk::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = lsof::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = mount::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = systemctl::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = top::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = nmap::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = iptables::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = crontab::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = env::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = who::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = last::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = dmesg::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = ss::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = route::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = arp::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = fsck::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = getfacl::try_compact(text) {
        return Some(out);
    }
    if let Some(out) = apropos::try_compact(text) {
        return Some(out);
    }
    None
}

#[cfg(test)]
mod ladder_shadowing_tests {
    /// The ladder returns the FIRST compactor whose `try_compact` answers, so a
    /// module that accepts anything makes every module after it unreachable.
    ///
    /// MEASURED 2026-08-04: five of the twenty-three listed here (`ping`,
    /// `mount`, `top`, `env`, `who`) have a `detect` of
    /// `!text.trim().is_empty()` — any non-empty text at all — and `ping` sits
    /// third.
    ///
    /// The fixtures are BULK on purpose: a two-line sample sits below every
    /// module's fold threshold, so nothing claims it and the test proves
    /// nothing. The first draft did exactly that and passed.
    ///
    /// MEASURED, and it refutes the obvious fix: making those five `detect`s
    /// specific would make the product WORSE. `systemctl`-shaped bulk output of
    /// 22 621 bytes comes back at 187 through the ladder as it stands, against
    /// 22 620 from `systemctl::compact` itself; `dmesg`, 18 180 bytes, gives 166
    /// against 13 489. What the greedy module reaches folds harder than the
    /// module that "owns" the shape. So the short-circuit is not a defect, and
    /// this test locks the property that actually matters — that whatever
    /// answers, answers with something SMALLER — rather than which module
    /// answers.
    #[test]
    fn no_listed_compactor_claims_output_that_is_not_its_own() {
        fn bulk(head: &str, row: &str) -> String {
            let mut s = String::from(head);
            for i in 0..400 {
                s.push_str(&row.replace("{i}", &i.to_string()));
            }
            s
        }
        let cases = [
            (
                "systemctl",
                bulk(
                    "UNIT   LOAD   ACTIVE SUB     DESCRIPTION\n",
                    "svc{i}.service  loaded active running Service number {i}\n",
                ),
            ),
            (
                "dmesg",
                bulk("", "[    0.{i}] ACPI: table {i} checksum verified\n"),
            ),
            ("crontab", bulk("", "{i} 3 * * * /usr/bin/job{i}.sh\n")),
            (
                "iptables",
                bulk(
                    "Chain INPUT (policy ACCEPT)\ntarget prot opt source destination\n",
                    "ACCEPT tcp -- 10.0.0.{i} anywhere\n",
                ),
            ),
        ];
        for (owner, text) in &cases {
            let Some(out) = super::dispatch(text) else {
                continue; // nothing claimed it — the named path still covers it
            };
            // The symptom is NOT a wrong banner — a greedy module returns the
            // text unchanged, with no banner at all. It is that the ladder
            // stopped early, so the module that owns this shape never ran and
            // the output comes back uncompacted.
            assert!(
                out.len() < text.len(),
                "{owner} output came back uncompacted ({} bytes in, {} out): a module earlier \
                 in the ladder answered for text that is not its own, so {owner}'s compactor \
                 never ran",
                text.len(),
                out.len()
            );
        }
    }
}
